/**
 * @deprecated v1 authoring pattern — hand-typed with a raw platform UUID,
 * exactly the "no ids in authored source" bug CLAUDE.md's Gotchas section
 * warns about. Superseded by the pulled `aiProviders` catalog: providers and
 * their connectors are discovered by `elementum pull org --data-only`, never
 * hand-authored (they hold credentials, manually configured on the
 * platform), and referenced as `catalog.aiProviders.<provider>.models.<model>`
 * — e.g. `connector: catalog.aiProviders.anthropic.models.claudeOpus_4_6`.
 * Kept only because it's re-exported through the published
 * `@elementumai/edk/core` entry; do not use in new code.
 */
export interface AiProviderConnector {
    readonly id: string;
    readonly name?: string;
    /** Model identifier (e.g. "gpt-4o", "claude-3-5-sonnet"). Metadata only — the platform uses the connector's configured model. */
    readonly model?: string;
}
/** @deprecated Use the pulled `catalog.aiProviders.<provider>.models.<model>` token instead — see {@link AiProviderConnector}. */
export declare function aiProviderConnector(opts: {
    id: string;
    name?: string;
    model?: string;
}): AiProviderConnector;
